81	
82	    /**
83	     * Pragmatic syntactic check for an email address: a non-empty local part, a single {@code @}, and a
84	     * domain with at least one dot and a two-or-more-letter final label. Whitespace is not permitted.
85	     */
86	    private static final Pattern EMAIL_PATTERN =
87	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@.]{2,}$");
88	
89	    /**
90	     * Domains that supply disposable / throwaway mailboxes. An owner whose email domain matches one of
91	     * these (compared case-insensitively) is rejected. Values are stored lower-cased for comparison.
92	     */
93	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
94	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
95	
96	    /**
97	     * Dedicated audit logger. Successful side-effecting operations (such as creating an owner) emit a
98	     * line here so audit trails can be captured independently of application logging.
99	     */
100	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
101	
102	    /**
103	     * The request header carrying a client-supplied idempotency key for the create endpoint. When a create
104	     * repeats with a key already seen, the originally created owner is returned instead of a duplicate.
105	     */
106	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
107	
108	    /**
109	     * Remembers the id of the owner originally created for each seen {@code Idempotency-Key}. A repeated
110	     * create carrying an already-seen key is answered from this map with the original owner rather than
111	     * creating a duplicate.
112	     */
113	    private static final Map<String, Integer> IDEMPOTENT_CREATES = new ConcurrentHashMap<>();
