308	    /**
309	     * Rejects an owner payload that is missing or blank in any mandatory field. This complements Bean
310	     * Validation, which cannot reject whitespace-only values that still satisfy a minimum-length constraint.
311	     *
312	     * @param fields the submitted owner fields
313	     * @throws RequiredFieldsMissingException if any of firstName, lastName, city or telephone is
314	     *                                        {@code null} or blank, or if the owner supplies no address
315	     *                                        in either form (a blank structured {@code addressLine1} and a
316	     *                                        blank flat {@code address}, each measured after normalization)
317	     */
318	    /**
319	     * Reads the client-supplied {@code Idempotency-Key} header for the current create request, if any.
320	     *
321	     * @return the trimmed idempotency key, or {@code null} when the header is absent or blank
322	     */
323	    private String idempotencyKey() {
324	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
325	        if (key == null || key.isBlank()) {
326	            return null;
327	        }
328	        return key.strip();
329	    }
330	
331	    private void rejectMissingOrBlankFields(OwnerFieldsDto fields) {
332	        List<String> missing = new ArrayList<>();
333	        if (isBlank(fields.getFirstName())) {
334	            missing.add("firstName");
335	        }
336	        if (isBlank(fields.getLastName())) {
337	            missing.add("lastName");
338	        }
339	        boolean hasStructuredAddress = !isBlank(normalizeAddress(fields.getAddressLine1()));
340	        boolean hasFlatAddress = !isBlank(normalizeAddress(fields.getAddress()));
341	        if (!hasStructuredAddress && !hasFlatAddress) {
342	            missing.add("address");
343	        }
344	        if (isBlank(fields.getCity())) {
345	            missing.add("city");
346	        }
347	        if (isBlank(fields.getTelephone())) {
348	            missing.add("telephone");
349	        }
350	        if (!missing.isEmpty()) {
351	            throw new RequiredFieldsMissingException(missing);
352	        }
353	    }
354	
355	    private boolean isBlank(String value) {
356	        return value == null || value.isBlank();
357	    }
358	
359	    /**
360	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
361	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
362	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
363	     */
364	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
365	        "NSW", new int[] {2000, 2099},
366	        "VIC", new int[] {3000, 3099},
367	        "QLD", new int[] {4000, 4099});
368	
369	    /**
370	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
371	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
372	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
373	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
374	     *
375	     * @param postcode the submitted postcode, or {@code null} when omitted
376	     * @param city the owner's city, used to derive the region whose range constrains the postcode
377	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
378	     *                                  city's region
379	     */
380	    private void validatePostcode(String postcode, String city) {
381	        if (postcode == null) {
382	            return;
383	        }
384	        if (!postcode.matches("[0-9]{4}")) {
385	            throw new InvalidPostcodeException(postcode);
386	        }
387	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
388	        if (range == null) {
389	            return;
390	        }
391	        int value = Integer.parseInt(postcode);
392	        if (value < range[0] || value > range[1]) {
393	            throw new InvalidPostcodeException(postcode);
394	        }
395	    }
396	
397	    /**
398	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
399	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
400	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
401	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
402	     * <p>
403	     * Where a per-country rule is defined the national-number length is validated against the country
404	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
405	     * requires exactly 10.
406	     *
407	     * @param telephone the raw telephone value from the request
408	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
409	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
410	     */
411	    private String normalizeTelephone(String telephone) {
412	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
413	        String digits;
414	        if (cleaned.startsWith("+")) {
415	            digits = cleaned.substring(1);
416	        } else {
417	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
418	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
419	            digits = "61" + national;
420	        }
421	        if (!digits.matches("[0-9]{8,15}")) {
422	            throw new InvalidTelephoneException(cleaned);
423	        }
424	        // Validate the national-number length against the country code where a rule is defined.
425	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
426	            throw new InvalidTelephoneException(cleaned);
427	        }
428	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
429	            throw new InvalidTelephoneException(cleaned);
430	        }
431	        return "+" + digits;
432	    }
433	
434	    /**
435	     * Normalizes a submitted email address. A {@code null} email is left absent (the field is optional).
436	     * When present, it must be a syntactically valid address; the stored and returned value is trimmed and
437	     * lower-cased.
438	     *
439	     * @param email the raw email value from the request, or {@code null} if omitted
440	     * @return the lower-cased email, or {@code null} if none was supplied
441	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
442	     */
443	    private String normalizeEmail(String email) {
444	        if (email == null) {
445	            return null;
446	        }
447	        String trimmed = email.strip();
448	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
449	            throw new InvalidEmailException(email);
450	        }
451	        String normalized = trimmed.toLowerCase(Locale.ROOT);
452	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
453	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
454	            throw new DisposableEmailDomainException(domain);
455	        }
456	        return normalized;
457	    }
458	
459	    /**
460	     * Applies the owner's address in whichever form the request supplied, preferring the structured
461	     * fields. When a non-blank {@code addressLine1} is present, {@code addressLine1} and (when present)
462	     * {@code addressLine2} are normalized in place and the flat {@code address} is set to the composed
463	     * value: the normalized {@code addressLine1}, with a single space and the normalized
464	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the structured
465	     * lines are cleared and the flat {@code address} is normalized on its own, keeping the earlier
466	     * flat-address contract backward-compatible.
467	     *
468	     * @param owner the owner being created, mapped straight from the request
469	     */
470	    private void applyAddress(Owner owner) {
471	        if (!isBlank(owner.getAddressLine1())) {
472	            String line1 = normalizeAddress(owner.getAddressLine1());
473	            owner.setAddressLine1(line1);
474	            String composed = line1;
475	            if (!isBlank(owner.getAddressLine2())) {
476	                String line2 = normalizeAddress(owner.getAddressLine2());
477	                owner.setAddressLine2(line2);
478	                composed = line1 + " " + line2;
479	            } else {
480	                owner.setAddressLine2(null);
481	            }
482	            owner.setAddress(composed);
483	        } else {
484	            owner.setAddressLine1(null);
485	            owner.setAddressLine2(null);
486	            owner.setAddress(normalizeAddress(owner.getAddress()));
487	        }
488	    }
489	
490	    /**
