33	    /**
34	     * Points added when the owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more members.
35	     */
36	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
37	
38	    /**
39	     * The household size (members, including the owner) at which the large-household points are awarded.
40	     */
41	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
42	
43	    /**
44	     * Points added when the owner's tenure reaches {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
45	     */
46	    private static final int TENURE_POINTS = 3;
47	
48	    /**
49	     * Tenure, in elapsed fiscal years, that an owner must reach to earn the tenure points.
50	     */
51	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
52	
53	    /**
54	     * The month (1 July) on which the fiscal year starts.
55	     */
56	    private static final int FISCAL_YEAR_START_MONTH = 7;
57	
58	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
59	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
60	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
61	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
62	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() + \"-M\" + fiscalYearSuffix(owner.getRegistrationDate()))")
63	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
64	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
65	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
66	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.of(owner.getCity(), owner.getPostcode()))")
67	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.mapper.OwnerLocality.timezoneOf(owner.getCity(), owner.getPostcode()))")
68	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
69	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
70	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
