271	    /**
272	     * Handles {@link InvalidPostcodeException} raised when a submitted owner {@code postcode} is present
273	     * but is not a 4-digit value, or is out of range for the owner's city region (NSW 2000-2099,
274	     * VIC 3000-3099, QLD 4000-4099).
275	     *
276	     * @param e The {@link InvalidPostcodeException} to be handled
277	     * @param request {@link HttpServletRequest} object referring to the current request.
278	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
279	     */
280	    @ExceptionHandler(InvalidPostcodeException.class)
281	    @ResponseBody
282	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
283	        HttpStatus status = HttpStatus.BAD_REQUEST;
